def get_victim(bufs, hand):
    while True:
        b = bufs[hand]
        hand = (hand + 1) % len(bufs)
        if b.pins > 0:
            continue            # pinned: skip
        if b.usage > 0:
            b.usage -= 1        # second chance
            continue
        return b, hand          # usage 0: victim
